<template><div><div class="page-head"><div><h1>Products & Services</h1><p>Manage your catalogue, pricing and stock controls.</p></div><button class="btn btn-primary" @click="openCreate">+ Add item</button></div><div class="card mb-4 p-4"><div class="flex flex-col gap-3 md:flex-row"><input v-model="search" @keyup.enter="load" class="input md:max-w-sm" placeholder="Search SKU or name…"><select v-model="type" @change="load" class="input md:max-w-44"><option value="">All types</option><option value="product">Products</option><option value="service">Services</option></select><button class="btn btn-soft" @click="load">Refresh</button></div></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Item</th><th>Type</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td><div>{{p.name}}</div><div class="text-[10px] text-slate-400">{{p.sku}}</div></td><td class="capitalize">{{p.type}}</td><td>{{p.category?.name||'Uncategorised'}}</td><td>{{money(p.selling_price)}}</td><td>{{p.type==='service'?'—':p.stock_quantity}}</td><td><StatusBadge :value="p.is_active"/></td><td><div class="flex justify-end gap-2"><button class="btn btn-soft" @click="edit(p)">Edit</button><button class="btn btn-danger" @click="remove(p)">Delete</button></div></td></tr><tr v-if="!products.length"><td colspan="7"><div class="empty">No products or services found.</div></td></tr></tbody></table></div><AppModal :open="open" :title="editing?'Edit item':'Add product or service'" subtitle="Use services for non-stockable work." @close="open=false"><form @submit.prevent="save" class="grid grid-cols-1 gap-4 md:grid-cols-2"><div><label class="label">Name *</label><input v-model="form.name" class="input" required></div><div><label class="label">SKU *</label><input v-model="form.sku" class="input" required></div><div><label class="label">Type</label><select v-model="form.type" @change="syncType" class="input"><option value="product">Product</option><option value="service">Service</option></select></div><div><label class="label">Category</label><select v-model="form.category_id" class="input"><option :value="null">Uncategorised</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Cost price</label><MoneyInput v-model="form.cost_price" :min="0" /></div><div><label class="label">Selling price *</label><MoneyInput v-model="form.selling_price" :min="0" /></div><div><label class="label">Tax rate %</label><input v-model.number="form.tax_rate" class="input" type="number" min="0" max="100"></div><div><label class="label">Unit</label><input v-model="form.unit" class="input"></div><div v-if="form.type==='product'"><label class="label">Stock quantity</label><input v-model.number="form.stock_quantity" class="input" type="number" min="0"></div><div v-if="form.type==='product'"><label class="label">Minimum stock</label><input v-model.number="form.minimum_stock" class="input" type="number" min="0"></div><label v-if="form.type==='product'" class="md:col-span-2 flex items-center gap-2 text-xs font-semibold text-slate-600"><input v-model="form.track_stock" type="checkbox"> Track inventory for this item</label><label class="md:col-span-2 flex items-center gap-2 text-xs font-semibold text-slate-600"><input v-model="form.is_active" type="checkbox"> Active item</label><div class="md:col-span-2 flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" class="btn btn-soft" @click="open=false">Cancel</button><button class="btn btn-primary">{{saving?'Saving…':'Save item'}}</button></div></form></AppModal><div v-if="error" class="fixed bottom-5 right-5 rounded-xl bg-rose-600 px-4 py-3 text-xs font-bold text-white shadow-xl">{{error}}</div></div></template>
<script setup lang="ts">import MoneyInput from '../../components/MoneyInput.vue';import {onMounted,ref} from 'vue';import {api,apiError} from '../../services/api';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';import AppModal from '../../components/AppModal.vue';import StatusBadge from '../../components/StatusBadge.vue';const {ask:confirm}=useConfirm();const toast=useToast();const products=ref<any[]>([]),categories=ref<any[]>([]),search=ref(''),type=ref(''),open=ref(false),editing=ref<any>(null),saving=ref(false),error=ref('');const blank=()=>({name:'',sku:'',type:'product',category_id:null,cost_price:0,selling_price:0,tax_rate:0,unit:'pcs',stock_quantity:0,minimum_stock:0,track_stock:true,is_active:true});const form=ref<any>(blank());function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}async function load(){const [p,c]=await Promise.all([api.get('/products',{params:{search:search.value,type:type.value,per_page:30}}),api.get('/categories')]);products.value=p.data.data;categories.value=c.data}function openCreate(){editing.value=null;form.value=blank();open.value=true}function edit(p:any){editing.value=p;form.value={...blank(),...p};if(form.value.type==='service')form.value.track_stock=false;open.value=true}function syncType(){if(form.value.type==='service')form.value.track_stock=false}
async function save(){syncType();saving.value=true;error.value='';try{if(editing.value)await api.put(`/products/${editing.value.id}`,form.value);else await api.post('/products',form.value);open.value=false;await load();toast.success(editing.value?'Product updated':'Product created', editing.value?'Changes saved successfully.':'Product was created successfully.')}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}finally{saving.value=false}}async function remove(p:any){if(!(await confirm({title:'Delete product?',message:`You are about to delete ${p.name}. This action cannot be undone.`,confirmText:'Delete',danger:true})))return;try{await api.delete(`/products/${p.id}`);await load();toast.success('Product deleted', `${p.name} was deleted successfully.`)}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}}onMounted(load)</script>
